INSERT INTO `news` (`id`, `title`, `content`, `image`, `slider_images`, `user_id`, `created_at`, `updated_at`) VALUES
(1, 'برگزاری مسابقه امنیت سایبری - فتح پرچم در دانشگاه سجاد', '<p>                    مسابقه فتح پرچم در روز پنجشنبه مورخ ۲۱ فروردین ۱۴۰۴ در محل دانشگاه سجاد با حمایت مرکز مدیریت راهبردی افتا خراسان رضوی و شرکت خدمات علمی صنعتی خراسان برگزار گردید.&nbsp;<span style=\"color: rgb(33, 37, 41); background-color: var(--bs-body-bg); font-size: var(--bs-body-font-size); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">اهداف اولیه این مسابقه، آشنایی دانشجویان رشته کامپیوتر با مباحث مختلف امنیت سایبری و استعدادیابی در این حوزه می‌باشد.&nbsp;</span><span style=\"background-color: var(--bs-body-bg); font-size: var(--bs-body-font-size); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">این مسابقه از ساعت ۷:۳۰ لغایت ۱۴ ادامه داشته نتایج به شرح زیر اعلام می‌گردد:</span></p><table class=\"table table-bordered\"><tbody><tr><td style=\"text-align: center; \"><b>رتبه</b></td><td style=\"text-align: center;\"><b>نام دانشگاه</b></td><td style=\"text-align: center; \"><b>اسم تیم</b></td></tr><tr><td style=\"text-align: center;\">1</td><td style=\"text-align: center; \">شهید منتظری</td><td style=\"text-align: center; \">Sucrose</td></tr><tr><td style=\"text-align: center;\">2</td><td style=\"text-align: center; \">امام رضا</td><td style=\"text-align: center; \">Null</td></tr><tr><td style=\"text-align: center;\">3</td><td style=\"text-align: center; \">صنعتی قوچان</td><td style=\"text-align: center; \">Access Point</td></tr><tr><td style=\"text-align: center;\">4</td><td style=\"text-align: center; \">امام رضا</td><td style=\"text-align: center; \">Neuron</td></tr><tr><td style=\"text-align: center;\">5</td><td style=\"text-align: center; \">امام رضا</td><td style=\"text-align: center; \">Black Pixel</td></tr></tbody></table><p><br></p><p>سایت مسابقه:&nbsp; 🖇 <a href=\"https://mashhad-ctf.ir\" target=\"_blank\">https://mashhad-ctf.ir</a><a href=\"https://mashhad-ctf.ir\" target=\"_blank\"></a></p><p><br></p><p>\r\n\r\n\r\n                </p>', '6851c516ba5ae.jpg', NULL, 1, '2025-05-18 18:25:44', '2025-06-17 19:43:51'),
(2, 'مراسم اختتامیه مسابقه فتح پرچم (CTF)', '<p><span style=\"background-color: var(--bs-body-bg); font-size: var(--bs-body-font-size); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\">نخستین دوره از مسابقات سراسری فتح پرچم با محتوای  امنیت سایبری با حضور دکتر طالبی معاونت آموزش و تحقیقات و دکتر مظهر معاونت فنی مرکز مدیریت راهبردی افتای ریاست جمهوری به همراه مهندس آقایی رئیس مرکز افتای خراسان رضوی و معاونین در مورخ ۱۴۰۴/۱/۲۱ در محل دانشگاه سجاد برگزار گردید. در این دوره از مسابقات تعداد ۱۲۰ شرکت‌کننده در قالب ۵۳ تیم از دانشگاه‌های برجسته استان خراسان بزرگ حضور داشتند.</span></p><p><span style=\"background-color: var(--bs-body-bg); font-size: var(--bs-body-font-size); font-weight: var(--bs-body-font-weight); text-align: var(--bs-body-text-align);\"><br></span></p>', '685123ba7b0ea.jpg', NULL, 1, '2025-06-11 18:40:05', '2025-06-18 00:24:10'),
(3, 'فراخوان جشنواره کاهش آسیب‌های فضای مجازی', '<p><span style=\"color: rgb(33, 37, 41);\">اگر دغدغه آسیب‌های فضای مجازی را دارید،</span><br style=\"color: rgb(33, 37, 41);\"><span style=\"color: rgb(33, 37, 41);\">اگر دستی بر قلم، دوربین، ایده یا طراحی دارید،</span><br style=\"color: rgb(33, 37, 41);\"><span style=\"color: rgb(33, 37, 41);\">و اگر می‌خواهید در مسیر اصلاح فرهنگی جامعه نقش‌آفرین باشید، در این حرکت فرهنگی اثرگذار، سهیم باشید.</span><br style=\"color: rgb(33, 37, 41);\"><br style=\"color: rgb(33, 37, 41);\"><span style=\"color: rgb(33, 37, 41);\">از همه‌ی علاقه‌مندان، اساتید، معلمان، هنرمندان، دانشجویان، دانش‌آموزان، شرکتها و فعالان رسانه‌ای و دغدغه‌مند دعوت می‌شود تا آثار خلاقانه و اثرگذار خود را در خصوص محورهای جشنواره برای دبیرخانه ارسال نمایند.</span><br style=\"color: rgb(33, 37, 41);\"><span style=\"color: rgb(33, 37, 41);\">آخرین مهلت ارسال آثار: <u>۳۱ مرداد ماه ۱۴۰۴</u></span><br style=\"color: rgb(33, 37, 41);\"><br style=\"color: rgb(33, 37, 41);\"><span style=\"color: rgb(33, 37, 41);\">اطلاعات بیشتر و ارسال آثار از طریق وب سایت جشنواره به آدرس&nbsp;</span><a href=\"http://www.smartngo.ir\" target=\"_blank\">www.smartngo.ir</a><br style=\"color: rgb(33, 37, 41);\"><span style=\"color: rgb(33, 37, 41);\">یا نشانی khrsmartngo@ در شبکه های اجتماعی و پیام‌رسان‌ها</span><br style=\"color: rgb(33, 37, 41);\"><br style=\"color: rgb(33, 37, 41);\"><span style=\"color: rgb(33, 37, 41);\">به آثار منتخب 2.000.000.000 ریال جایزه نقدی و جوایز ارزنده غیر نقد دیگر اهدا خواهد شد.</span><br style=\"color: rgb(33, 37, 41);\"><br style=\"color: rgb(33, 37, 41);\"><span style=\"color: rgb(33, 37, 41);\">منتظر خلاقیت‌های شما هستیم!</span><br style=\"color: rgb(33, 37, 41);\"><br style=\"color: rgb(33, 37, 41);\"><span style=\"color: rgb(33, 37, 41);\">(انجمن عام‌المنفعه هوشمندسازی استان خراسان رضوی)</span><br></p>', '684b391edc075.jpg', NULL, 1, '2025-06-12 19:31:26', '2025-06-18 00:26:47'),
(4, 'مراسم تقدیر از کادر اجرایی مسابقه فتح پرچم', '<div><br></div><div><div style=\"outline: none !important;\">مراسم تقدیر و تشکر از کادر اجرایی مسابقه فتح پرچم، روز سه‌شنبه، ۳۱ اردیبهشت ماه، با حضور نمایندگان محترم مرکز افتا خراسان رضوی و جمعی از مسئولین دانشگاه سجاد در محل این دانشگاه برگزار گردید.</div><div style=\"outline: none !important;\"><br></div><div style=\"outline: none !important;\">این مراسم به منظور ارج نهادن به تلاش‌های بی‌وقفه و زحمات شبانه‌روزی دست‌اندرکاران و کادر اجرایی مسابقه فتح پرچم برگزار شد. سخنرانان در این مراسم، ضمن تقدیر از سطح برگزاری و کیفیت بالای مسابقه، بر اهمیت برگزاری رویدادهایی از این دست در راستای کشف و پرورش استعدادهای جوان در حوزه امنیت سایبری تأکید کردند.<br clear=\"none\" style=\"outline: none !important;\"><br clear=\"none\" style=\"outline: none !important;\">در پایان مراسم، با اهدای لوح تقدیر و هدایایی، از زحمات و همکاری‌های ارزشمند تمامی اعضای کادر اجرایی مسابقه فتح پرچم قدردانی به عمل آمد.</div><div style=\"outline: none !important;\"><br></div></div>', '68507685b665c.jpg', '[\"6862b9a95ab2c.jpg\",\"6862b9a963f9e.jpg\",\"6862b9a96958f.jpg\",\"6862b9a96f350.jpg\"]', 1, '2025-06-16 18:54:45', '2025-06-30 15:22:01');

